// CrowdStrike CQL for Fake Mobile App Residential Proxy and Subscription Scam Detection
// Detection 1: Fake VPN acting as residential proxy
app_category="VPN" OR app_category="cleaner" OR app_category="optimizer" OR app_category="spam-blocker"
| groupBy([device_id, app_id], function=[
    count(field=dest_ip, distinct=true, as=unique_dest_ips),
    sum(bytes_out, as=total_bytes_out),
    sum(bytes_in, as=total_bytes_in),
    count(field=src_port, distinct=true, as=unique_src_ports),
    collect([app_name])
  ])
| proxy_ratio := round(total_bytes_in / total_bytes_out * 100) / 100
| unique_dest_ips > 50 AND proxy_ratio > 2
| risk := "residential_proxy_behavior"
